import{_ as t,o as e,c as r,ag as l}from"./chunks/framework.Aev9KvMf.js";const f=JSON.parse('{"title":"健康中国行动 · 健康生活方式与基础（行动 1—6）","description":"健康中国行动 1—6 分页：健康知识普及、合理膳食、全民健身、控烟、心理健康、健康环境——定位与量化方向速览。","frontmatter":{"title":"健康中国行动 · 健康生活方式与基础（行动 1—6）","issuer":"健康中国行动推进委员会","source_tier":"一级来源","version":"2019—2030","published":"2019-07","source_url":"https://www.gov.cn/xinwen/2019-07/15/content_5409694.htm","status":"现行","tags":["权威数据","健康中国","健康生活方式"],"type":"数据页","reviewed":false,"description":"健康中国行动 1—6 分页：健康知识普及、合理膳食、全民健身、控烟、心理健康、健康环境——定位与量化方向速览。"},"headers":[],"relativePath":"data/hc-action-lifestyle.md","filePath":"data/hc-action-lifestyle.md"}'),o={name:"data/hc-action-lifestyle.md"};function i(n,a,h,s,c,d){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="健康中国行动-·-健康生活方式与基础-行动-1—6" tabindex="-1">健康中国行动 · 健康生活方式与基础（行动 1—6） <a class="header-anchor" href="#健康中国行动-·-健康生活方式与基础-行动-1—6" aria-label="Permalink to &quot;健康中国行动 · 健康生活方式与基础（行动 1—6）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据 gov.cn 全文整理，尚未逐条对照原文校验；各行动的量化目标请以原文为准。</p></div><blockquote><p><strong>原文出处</strong>：《健康中国行动（2019—2030年）》（<a href="https://www.gov.cn/xinwen/2019-07/15/content_5409694.htm" target="_blank" rel="noreferrer">gov.cn 全文</a>）· 一级来源。本页为 15 个行动按主题展开的第一组（其余见<a href="/SageRelay/data/hc-action-people.html">重点人群</a>、<a href="/SageRelay/data/hc-action-disease.html">疾病防治</a>）。</p></blockquote><h2 id="行动-1-·-健康知识普及行动" tabindex="-1">行动 1 · 健康知识普及行动 <a class="header-anchor" href="#行动-1-·-健康知识普及行动" aria-label="Permalink to &quot;行动 1 · 健康知识普及行动&quot;">​</a></h2><p>让居民掌握应有的健康知识——<strong>本站的存在正是这条行动的家庭版实践</strong>：把权威文件讲清楚、附上出处。（<a href="https://www.gov.cn/xinwen/2019-07/15/content_5409694.htm" target="_blank" rel="noreferrer">gov.cn 全文</a>）</p><h2 id="行动-2-·-合理膳食行动" tabindex="-1">行动 2 · 合理膳食行动 <a class="header-anchor" href="#行动-2-·-合理膳食行动" aria-label="Permalink to &quot;行动 2 · 合理膳食行动&quot;">​</a></h2><ul><li>方向：成人每日食盐摄入量下降、超重肥胖增长势头减缓等量化目标（具体数值见原文）。</li><li>配套文件即本站核心：<a href="/SageRelay/guides/hypertension-2023.html">各慢病食养指南词条</a>。</li></ul><h2 id="行动-3-·-全民健身行动" tabindex="-1">行动 3 · 全民健身行动 <a class="header-anchor" href="#行动-3-·-全民健身行动" aria-label="Permalink to &quot;行动 3 · 全民健身行动&quot;">​</a></h2><ul><li>方向：经常参加体育锻炼人数比例提升。</li><li>量化依据：<a href="/SageRelay/data/physical-activity-2021.html">身体活动指南分人群推荐量</a>。</li></ul><h2 id="行动-4-·-控烟行动" tabindex="-1">行动 4 · 控烟行动 <a class="header-anchor" href="#行动-4-·-控烟行动" aria-label="Permalink to &quot;行动 4 · 控烟行动&quot;">​</a></h2><ul><li>方向：15 岁以上人群吸烟率下降；各指南&quot;戒烟限酒&quot;条款的政策来源。</li></ul><h2 id="行动-5-·-心理健康促进行动" tabindex="-1">行动 5 · 心理健康促进行动 <a class="header-anchor" href="#行动-5-·-心理健康促进行动" aria-label="Permalink to &quot;行动 5 · 心理健康促进行动&quot;">​</a></h2><ul><li>方向：居民心理健康素养水平提升、失眠与焦虑抑郁障碍患病率趋势干预。各指南&quot;心理平衡、规律作息&quot;条款的政策来源（如<a href="/SageRelay/guides/hypertension-2023.html">高血压</a>）。</li></ul><h2 id="行动-6-·-健康环境促进行动" tabindex="-1">行动 6 · 健康环境促进行动 <a class="header-anchor" href="#行动-6-·-健康环境促进行动" aria-label="Permalink to &quot;行动 6 · 健康环境促进行动&quot;">​</a></h2><ul><li>方向：环境健康风险防范（饮水、空气、居家安全等），与<a href="/SageRelay/assist.html">家庭管家</a>的&quot;家庭防护&quot;场景相关。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>健康中国行动推进委员会（国务院）</td></tr><tr><td>版本</td><td>2019—2030（现行）</td></tr><tr><td>原文直链</td><td><a href="https://www.gov.cn/xinwen/2019-07/15/content_5409694.htm" target="_blank" rel="noreferrer">gov.cn 全文</a></td></tr></tbody></table>',17)])])}const p=t(o,[["render",i]]);export{f as __pageData,p as default};
